from pathlib import Path
import json
ROOT=Path(__file__).parent
apps=[]
def add(slug,title,category,icon,tagline,html,js,tech='JavaScript • HTML • CSS',level='Intermediate'):
 d=ROOT/'apps'/slug;d.mkdir(parents=True,exist_ok=True)
 d.joinpath('index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080b11"><meta name="description" content="{title} — a working coding showcase by Sharanya Pal"><title>{title} · SP Dev Labs</title><link rel="stylesheet" href="../../assets/app.css"></head><body><div class="shell"><header class="top"><a class="logo" href="../../index.html">SP<span style="color:#fff">/</span>LABS.</a><a class="back" href="../../index.html">← All projects</a></header><div class="meta">LIVE APPLICATION · {category.upper()} · {level.upper()}</div><h1>{icon} <em>{title}</em></h1><p class="lead">{tagline}</p><main class="workspace">{html}</main><footer class="foot">Built by Sharanya Pal · Local-first browser demo. No data is sent to a server. · <a href="https://github.com/sharanyapal/sharanya-pal-portfolio/tree/main/labs/apps/{slug}">View source</a></footer></div><script src="../../assets/app.js"></script><script src="app.js"></script></body></html>''',encoding='utf8')
 d.joinpath('app.js').write_text(js.strip()+"\n",encoding='utf8')
 apps.append(dict(id=slug,title=title,category=category,icon=icon,desc=tagline,tech=tech,level=level,url='apps/'+slug+'/index.html',live=True,language='JavaScript'))

add('access-matrix','Access Matrix','Security','🛡️','Interactive role-based access control. Assign permissions and run least-privilege checks.', '''<section class="panel"><h2>Identity session</h2><label for="role">Acting role</label><select id="role"><option>Viewer</option><option>Analyst</option><option>Administrator</option><option>Auditor</option></select><label for="resource">Resource</label><select id="resource"><option value="reports">Reports</option><option value="users">User directory</option><option value="secrets">Secrets vault</option><option value="audit">Audit logs</option></select><label for="action">Requested action</label><select id="action"><option>read</option><option>write</option><option>delete</option><option>approve</option></select><div class="actions"><button id="check">Evaluate request</button><button class="secondary" id="reset">Reset policy</button></div><p class="tiny">Rules are demonstrative; no live systems are accessed.</p></section><section class="panel"><h2>Policy decision</h2><div id="decision" class="output" aria-live="polite">Choose a role, resource, and action.</div><h2>Permission matrix</h2><div id="matrix"></div></section>''','''const POLICY={Viewer:{reports:['read']},Analyst:{reports:['read','write'],users:['read'],audit:['read']},Administrator:{reports:['read','write','delete'],users:['read','write','delete','approve'],secrets:['read','write'],audit:['read']},Auditor:{reports:['read'],audit:['read']}};
function matrix(){const h=['reports','users','secrets','audit'];document.querySelector('#matrix').innerHTML='<table><tr><th>Resource</th><th>Actions</th></tr>'+h.map(k=>'<tr><td>'+k+'</td><td>'+safe((POLICY[$('#role').value][k]||[]).join(', ')||'—')+'</td></tr>').join('')+'</table>'}
function check(){const r=$('#role').value,s=$('#resource').value,a=$('#action').value;const allowed=(POLICY[r][s]||[]).includes(a);show('#decision',(allowed?'✅ ALLOW':'⛔ DENY')+'\\n'+r+' → '+a.toUpperCase()+' / '+s+'\\nPolicy: '+(allowed?'explicit permission matched':'default deny (least privilege)'));matrix()}
$('#check').onclick=check;$('#role').onchange=matrix;$('#reset').onclick=()=>{$('#role').value='Viewer';$('#resource').value='reports';$('#action').value='read';check()};check();''')

add('password-forge','Password Forge','Security','🔑','Cryptographically secure password generator with adjustable entropy and strength guidance.', '''<section class="panel"><h2>Generate secure credentials</h2><label for="length">Length: <b id="lengthValue">20</b></label><input id="length" type="range" min="8" max="64" value="20"><div class="row"><label><input type="checkbox" id="upper" checked style="width:auto"> Uppercase</label><label><input type="checkbox" id="numbers" checked style="width:auto"> Digits</label><label><input type="checkbox" id="special" checked style="width:auto"> Symbols</label></div><div class="actions"><button id="generate">Generate</button><button class="secondary" id="copy">Copy password</button></div><p class="tiny">Passwords are generated entirely on your device using Web Crypto.</p></section><section class="panel"><h2>Generated password</h2><div id="password" class="output" aria-live="polite"></div><p>Estimated entropy: <strong id="entropy"></strong> bits</p><p class="tiny" id="hint"></p></section>''','''const randInt=(n)=>{const limit=Math.floor(4294967296/n)*n;let x;do{x=crypto.getRandomValues(new Uint32Array(1))[0]}while(x>=limit);return x%n};function generate(){const sets=['abcdefghijkmnopqrstuvwxyz'];if($('#upper').checked)sets.push('ABCDEFGHJKLMNPQRSTUVWXYZ');if($('#numbers').checked)sets.push('23456789');if($('#special').checked)sets.push('!@#$%^&*_-+=?');const len=Number($('#length').value),alphabet=sets.join('');let p=sets.map(x=>x[randInt(x.length)]);while(p.length<len)p.push(alphabet[randInt(alphabet.length)]);for(let i=p.length-1;i>0;i--){const j=randInt(i+1);[p[i],p[j]]=[p[j],p[i]]}show('#password',p.join(''));const bits=len*Math.log2(alphabet.length);show('#entropy',bits.toFixed(1));show('#hint',bits>=100?'High theoretical entropy. Save in a password manager.':'Increase length for stronger protection.')}$('#length').oninput=e=>{show('#lengthValue',e.target.value);generate()};for(const id of ['upper','numbers','special'])$('#'+id).onchange=generate;$('#generate').onclick=generate;$('#copy').onclick=async()=>{await navigator.clipboard.writeText($('#password').textContent);show('#hint','Copied to clipboard; avoid sharing secrets.')};generate();''')

add('json-studio','JSON Studio','Developer Tools','🧩','Format, validate, minify, and inspect nested JSON with precise parsing errors.', '''<section class="panel"><h2>Input document</h2><label for="json">JSON text</label><textarea id="json" spellcheck="false">{"team":"identity","members":[{"name":"Alex","role":"analyst"}],"active":true}</textarea><div class="actions"><button id="format">Pretty-print</button><button class="secondary" id="minify">Minify</button><button class="secondary" id="example">Load sample</button></div></section><section class="panel"><h2>Parsing result</h2><div id="result" class="output" aria-live="polite"></div><div class="actions"><button class="secondary" id="copy">Copy output</button><button class="secondary" id="save">Download JSON</button></div></section>''','''let output='';function parse(mode){try{const obj=JSON.parse($('#json').value);output=JSON.stringify(obj,null,mode==='minify'?0:2);show('#result','✓ VALID JSON\\n\\n'+output);return true}catch(e){output='';show('#result','✕ PARSE ERROR\\n'+e.message);return false}}$('#format').onclick=()=>{if(parse('format'))$('#json').value=output};$('#minify').onclick=()=>{if(parse('minify'))$('#json').value=output};$('#example').onclick=()=>{$('#json').value=JSON.stringify({system:'identity',roles:['admin','analyst'],policy:{default:'deny',mfa:true}},null,2);parse('format')};$('#copy').onclick=()=>{if(output)navigator.clipboard.writeText(output)};$('#save').onclick=()=>{if(parse('format'))downloadText('document.json',output,'application/json')};$('#json').oninput=()=>parse('format');parse('format');''')

add('regex-lab','Regex Lab','Developer Tools','🧪','Test regular expressions against real strings with match spans, flags, and error handling.', '''<section class="panel"><h2>Expression</h2><label for="pattern">Regex pattern</label><input id="pattern" value="[A-Z][a-z]+"><label for="flags">Flags</label><select id="flags"><option value="g">g · global</option><option value="gi">gi · case insensitive</option><option value="gm">gm · multiline</option><option value="gim">gim · both</option></select><label for="text">Test text</label><textarea id="text">Westpac IAM team uses ServiceNow and Python. Identity matters.</textarea></section><section class="panel"><h2>Match results</h2><div id="output" class="output" aria-live="polite"></div><h2>Highlighted matches</h2><div id="highlight" class="output" style="white-space:pre-wrap"></div></section>''','''function run(){try{const text=$('#text').value,reg=new RegExp($('#pattern').value,$('#flags').value),found=[...text.matchAll(reg)];show('#output',found.length+' match(es)\\n'+found.slice(0,120).map((m,i)=>'#'+(i+1)+' ['+m.index+':'+(m.index+m[0].length)+'] '+JSON.stringify(m[0])).join('\\n'));let html='',pos=0;for(const m of found){if(m.index<pos)continue;html+=safe(text.slice(pos,m.index))+'<mark style="background:#c5ff6b;color:#071107">'+safe(m[0])+'</mark>';pos=m.index+m[0].length}$('#highlight').innerHTML=html+safe(text.slice(pos))}catch(e){show('#output','Invalid regular expression: '+e.message);$('#highlight').textContent=$('#text').value}}['pattern','flags','text'].forEach(id=>$('#'+id).addEventListener('input',run));run();''')

add('csv-insights','CSV Insights','Data Science','📊','Upload CSV data, preview the schema, and generate a simple category aggregation chart.', '''<section class="panel"><h2>Load dataset</h2><input type="file" id="file" accept=".csv,text/csv"><label for="csv">Or paste CSV</label><textarea id="csv">category,revenue,month\nIAM,150,Jan\nAI,80,Jan\nWeb,120,Jan\nIAM,170,Feb\nAI,140,Feb\nWeb,125,Feb</textarea><div class="grid"><div><label for="group">Group by</label><select id="group"></select></div><div><label for="metric">Sum numeric column</label><select id="metric"></select></div></div><div class="actions"><button id="analyze">Analyze</button></div></section><section class="panel"><h2>Dataset snapshot</h2><div id="summary" class="output"></div><canvas id="chart" width="570" height="320" role="img" aria-label="Aggregated bar chart"></canvas><div id="preview" style="overflow:auto"></div></section>''','''function parseCSV(src){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<src.length;i++){const c=src[i];if(c==='"'){if(quoted&&src[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\\n'||c==='\\r')&&!quoted){if(c==='\\r'&&src[i+1]==='\\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(quoted)throw Error('Unclosed quotation mark');const width=rows[0]?.length||0;if(rows.some(r=>r.length!==width))throw Error('All rows must have the same number of columns');return rows}let rows=[];function options(){rows=parseCSV($('#csv').value);if(rows.length<2)throw Error('Provide a header and at least one row');const names=rows[0];$('#group').innerHTML=names.map((x,i)=>'<option value="'+i+'">'+safe(x)+'</option>').join('');$('#metric').innerHTML=names.map((x,i)=>'<option value="'+i+'">'+safe(x)+'</option>').join('');$('#metric').selectedIndex=Math.min(1,names.length-1)}function analyze(){try{rows=parseCSV($('#csv').value);if(rows.length<2)throw Error('Insufficient rows');const group=Number($('#group').value),metric=Number($('#metric').value),counts={};for(const r of rows.slice(1)){const val=Number(r[metric]);if(!Number.isFinite(val))continue;counts[r[group]]=(counts[r[group]]||0)+val}const result=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,10);show('#summary',`${rows.length-1} rows · ${rows[0].length} columns · ${result.length} chart categories`);$('#preview').innerHTML='<table><tr>'+rows[0].map(x=>'<th>'+safe(x)+'</th>').join('')+'</tr>'+rows.slice(1,6).map(r=>'<tr>'+r.map(x=>'<td>'+safe(x)+'</td>').join('')+'</tr>').join('')+'</table>';const c=$('#chart'),g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);if(!result.length)throw Error('Selected numeric field has no numbers');const max=Math.max(...result.map(v=>Math.max(0,v[1])),1);result.forEach(([name,value],i)=>{let y=20+i*29;g.fillStyle='#a4b5b9';g.font='12px monospace';g.fillText(name.slice(0,16),4,y+13);g.fillStyle='#c5ff6b';g.fillRect(154,y,Math.max(0,value)/max*340,19);g.fillStyle='#fff';g.fillText(String(value),504,y+14)})}catch(e){show('#summary','Error: '+e.message)}}$('#csv').onchange=()=>{try{options();analyze()}catch(e){show('#summary',e.message)}};$('#file').onchange=async e=>{const f=e.target.files[0];if(f){if(f.size>2e6){show('#summary','Maximum 2 MB CSV');return}$('#csv').value=await f.text();try{options();analyze()}catch(err){show('#summary',err.message)}}};$('#analyze').onclick=analyze;options();analyze();''')

add('hash-studio','Hash Studio','Security','🧬','Compute SHA-256, SHA-384, and SHA-512 digests for text or local files using browser Web Crypto.', '''<section class="panel"><h2>Input material</h2><label for="message">Text to hash</label><textarea id="message">Identity is the new security perimeter.</textarea><label for="file">Or select local file</label><input id="file" type="file"><label for="algorithm">Algorithm</label><select id="algorithm"><option value="SHA-256">SHA-256</option><option value="SHA-384">SHA-384</option><option value="SHA-512">SHA-512</option></select><div class="actions"><button id="run">Calculate digest</button><button class="secondary" id="copy">Copy hash</button></div></section><section class="panel"><h2>Digest and properties</h2><div id="out" class="output" aria-live="polite"></div><p class="tiny">Hashing is one-way integrity verification, not encryption. Files are processed on-device.</p></section>''','''let last='';async function hash(){try{const f=$('#file').files[0];if(f&&f.size>20e6)throw Error('Demo limit: 20 MB per file');const bytes=f?await f.arrayBuffer():new TextEncoder().encode($('#message').value);const digest=await crypto.subtle.digest($('#algorithm').value,bytes);last=[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');show('#out',$('#algorithm').value+'\\n'+last+'\\n\\nInput: '+(f?f.name:'UTF-8 text')+' · '+bytes.byteLength+' bytes')}catch(e){show('#out',e.message)}}$('#run').onclick=hash;$('#copy').onclick=()=>last&&navigator.clipboard.writeText(last);$('#algorithm').onchange=hash;hash();''')

add('sorting-arena','Sorting Arena','Algorithms','🏎️','Watch bubble sort, insertion sort, or selection sort operate on randomized arrays.', '''<section class="panel"><h2>Algorithm controls</h2><label for="algorithm">Algorithm</label><select id="algorithm"><option>bubble</option><option>insertion</option><option>selection</option></select><label for="count">Elements: <b id="countText">24</b></label><input type="range" min="8" max="55" value="24" id="count"><label for="delay">Delay in milliseconds</label><input id="delay" type="number" min="0" max="250" value="35"><div class="actions"><button id="start">Run animation</button><button class="secondary" id="shuffle">Shuffle</button></div><div id="stats" class="output" style="margin-top:14px;min-height:55px"></div></section><section class="panel"><h2>State of the array</h2><canvas id="canvas" width="600" height="340" role="img" aria-label="Array bars being sorted"></canvas></section>''','''let arr=[],running=false,comparisons=0,swaps=0;const canvas=$('#canvas'),ctx=canvas.getContext('2d');function draw(a=-1,b=-1){ctx.clearRect(0,0,600,340);const w=600/arr.length;arr.forEach((v,i)=>{ctx.fillStyle=i===a||i===b?'#f4b879':'#c5ff6b';ctx.fillRect(i*w+2,338-v*3,(w-3),v*3)}) ;show('#stats',`Comparisons: ${comparisons} · Moves: ${swaps}`)}function shuffle(){if(running)return;const n=Number($('#count').value);arr=Array.from({length:n},()=>6+Math.floor(Math.random()*101));comparisons=swaps=0;draw()}const wait=()=>new Promise(r=>setTimeout(r,Math.max(0,Math.min(250,Number($('#delay').value)||0))));async function run(){if(running)return;running=true;$('#start').disabled=$('#shuffle').disabled=true;const algo=$('#algorithm').value;const cmp=async(i,j)=>{comparisons++;draw(i,j);await wait();return arr[i]>arr[j]};const swap=async(i,j)=>{[arr[i],arr[j]]=[arr[j],arr[i]];swaps++;draw(i,j);await wait()};try{if(algo==='bubble'){for(let i=0;i<arr.length;i++)for(let j=0;j<arr.length-i-1;j++)if(await cmp(j,j+1))await swap(j,j+1)}else if(algo==='selection'){for(let i=0;i<arr.length;i++){let min=i;for(let j=i+1;j<arr.length;j++){comparisons++;if(arr[j]<arr[min])min=j;draw(min,j);await wait()}if(min!==i)await swap(i,min)}}else{for(let i=1;i<arr.length;i++){let j=i;while(j>0&&await cmp(j-1,j)){await swap(j-1,j);j--}}}}finally{running=false;$('#start').disabled=$('#shuffle').disabled=false;draw()}}$('#count').oninput=e=>{show('#countText',e.target.value);shuffle()};$('#shuffle').onclick=shuffle;$('#start').onclick=run;shuffle();''')

add('markdown-studio','Markdown Studio','Developer Tools','📝','A deliberately safe Markdown previewer supporting headings, lists, links, emphasis, and code.', '''<section class="panel"><h2>Markdown source</h2><textarea id="src" style="min-height:320px"># Release notes\n\n**Identity** workflows are improving.\n\n- Enforce least privilege\n- Review access monthly\n\n`policy == allow`\n\n[Learn Markdown](https://www.markdownguide.org/)</textarea><button class="secondary" id="export">Export .md</button></section><section class="panel"><h2>Rendered preview</h2><div class="output" style="font-family:inherit" id="preview"></div><p class="tiny">HTML is escaped before Markdown rendering to prevent embedded scripts.</p></section>''','''function render(md){let lines=md.split('\\n').map(safe);const inline=s=>s.replace(/\\*\\*([^*]+)\\*\\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code style="color:#c5ff6b">$1</code>').replace(/\\[([^\\]]+)\\]\\((https?:\\/\\/[^ )]+)\\)/g,(_m,t,u)=>'<a href="'+u+'" target="_blank" rel="noopener noreferrer">'+t+'</a>');let out='',ul=false;for(const l of lines){if(l.startsWith('- ')){if(!ul){out+='<ul>';ul=true}out+='<li>'+inline(l.slice(2))+'</li>';continue}if(ul){out+='</ul>';ul=false}const head=l.match(/^(#{1,3}) (.*)$/);if(head){const n=head[1].length;out+='<h'+n+'>'+inline(head[2])+'</h'+n+'>'}else if(l)out+='<p>'+inline(l)+'</p>';else out+='<div style="height:10px"></div>'}if(ul)out+='</ul>';return out}function update(){$('#preview').innerHTML=render($('#src').value)}$('#src').oninput=update;$('#export').onclick=()=>downloadText('notes.md',$('#src').value,'text/markdown');update();''')

add('neon-runner','Neon Runner','Game Dev','👾','Playable keyboard/touch retro dodge game with score tracking and restart mechanics.', '''<section class="panel wide"><div class="row" style="justify-content:space-between"><h2>Arcade mode / dodge the hazards</h2><div><span class="pill" id="score">Score 0</span><span class="pill" id="best">Best 0</span></div></div><canvas id="game" width="820" height="370" style="background:#071522;border:1px solid #335269;border-radius:10px;max-height:380px" tabindex="0" role="img" aria-label="Retro arcade dodge game"></canvas><div class="actions"><button id="start">Start / Restart</button><button class="secondary" id="left">← Left</button><button class="secondary" id="right">Right →</button></div><p class="tiny">Use ← and → or A and D. On mobile, hold the buttons to move. Survive as long as you can.</p><div id="status" class="output">Press Start to play.</div></section>''','''const c=$('#game'),g=c.getContext('2d'),W=820,H=370;let player=400,obstacles=[],playing=false,score=0,best=Number(localStorage.getItem('neon-best')||0),last=0,spawn=0,dirs={left:false,right:false};show('#best','Best '+best);function loop(t){if(!playing)return;const dt=Math.min((t-last)/1000,.05);last=t;g.fillStyle='#071522';g.fillRect(0,0,W,H);g.strokeStyle='#133242';for(let x=0;x<W;x+=40){g.beginPath();g.moveTo(x,0);g.lineTo(x,H);g.stroke()}if(dirs.left)player=Math.max(14,player-dt*390);if(dirs.right)player=Math.min(W-14,player+dt*390);spawn+=dt;if(spawn>.55){spawn=0;obstacles.push({x:16+Math.random()*(W-36),y:-20,sz:14+Math.random()*17})}for(const o of obstacles){o.y+=(170+score*.18)*dt;g.fillStyle='#f48fa2';g.fillRect(o.x-o.sz/2,o.y,o.sz,o.sz);if(o.y+o.sz>H-52&&o.y<H-20&&Math.abs(o.x-player)<o.sz/2+13){playing=false;show('#status','Game over! Final score '+Math.floor(score)+' · Press Start to retry.');if(score>best){best=Math.floor(score);localStorage.setItem('neon-best',String(best));show('#best','Best '+best)}}}obstacles=obstacles.filter(o=>o.y<H+30);g.fillStyle='#c5ff6b';g.fillRect(player-15,H-54,30,30);score+=dt*20;show('#score','Score '+Math.floor(score));if(playing)requestAnimationFrame(loop)}$('#start').onclick=()=>{player=400;obstacles=[];score=0;last=performance.now();spawn=0;playing=true;show('#status','Run started. Dodge incoming hazards.');c.focus();requestAnimationFrame(loop)};document.addEventListener('keydown',e=>{if(['ArrowLeft','a','A'].includes(e.key))dirs.left=true;if(['ArrowRight','d','D'].includes(e.key))dirs.right=true;if(['ArrowLeft','ArrowRight'].includes(e.key)&&document.activeElement===c)e.preventDefault()});document.addEventListener('keyup',e=>{if(['ArrowLeft','a','A'].includes(e.key))dirs.left=false;if(['ArrowRight','d','D'].includes(e.key))dirs.right=false});for(const [id,key]of [['left','left'],['right','right']]){const b=$('#'+id);b.addEventListener('pointerdown',e=>{e.preventDefault();dirs[key]=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>dirs[key]=false))}''')

add('finance-engine','Finance Engine','Productivity','💹','Loan EMI and compound-growth calculators with formulas, breakdowns, and sanity checks.', '''<section class="panel"><h2>Loan EMI</h2><label for="principal">Principal (₹)</label><input id="principal" type="number" min="0" value="500000"><div class="grid"><div><label for="rate">Annual rate (%)</label><input id="rate" type="number" min="0" step=".1" value="9"></div><div><label for="months">Months</label><input id="months" type="number" min="1" value="60"></div></div><div class="actions"><button id="calc">Calculate</button></div><div id="loanout" class="output" style="margin-top:15px"></div></section><section class="panel"><h2>Compound growth</h2><label for="initial">Initial investment (₹)</label><input id="initial" type="number" min="0" value="100000"><div class="grid"><div><label for="growth">Annual return (%)</label><input id="growth" type="number" value="8" step=".1"></div><div><label for="years">Years</label><input id="years" type="number" min="1" value="10"></div></div><div class="actions"><button id="compute">Project growth</button></div><div id="investout" class="output" style="margin-top:15px"></div><p class="tiny">Illustrative calculations only, not investment advice.</p></section>''','''function money(n){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(n)}function loan(){const p=Number($('#principal').value),r=Number($('#rate').value)/1200,n=Number($('#months').value);if(p<0||r<0||n<1||![p,r,n].every(Number.isFinite))return show('#loanout','Enter nonnegative values and a positive number of months.');const emi=r===0?p/n:p*r/(1-Math.pow(1+r,-n));show('#loanout','Monthly EMI: '+money(emi)+'\\nTotal payable: '+money(emi*n)+'\\nTotal interest: '+money(emi*n-p))}function invest(){const p=Number($('#initial').value),r=Number($('#growth').value)/100,n=Number($('#years').value);if(p<0||r<=-1||n<0||![p,r,n].every(Number.isFinite))return show('#investout','Enter valid investment, rate and duration.');const v=p*Math.pow(1+r,n);show('#investout','Projected value: '+money(v)+'\\nEstimated gain: '+money(v-p)+'\\nFormula: P × (1 + r)^t')}$('#calc').onclick=loan;$('#compute').onclick=invest;loan();invest();''')

add('taskflow','TaskFlow Board','Productivity','🗂️','Local Kanban work board with priorities, status transitions, filtering, and persistence.', '''<section class="panel"><h2>Create task</h2><label for="task">Task title</label><input id="task" placeholder="Review SSO access policies" maxlength="90"><label for="priority">Priority</label><select id="priority"><option>High</option><option>Medium</option><option>Low</option></select><div class="actions"><button id="add">Add task</button><button class="secondary" id="clear">Clear completed</button></div><p class="tiny">Tasks are saved only in this browser's local storage.</p></section><section class="panel"><h2>Board status</h2><div id="summary" class="output"></div><label for="filter">Filter tasks</label><select id="filter"><option value="all">All</option><option value="Todo">To do</option><option value="Doing">Doing</option><option value="Done">Done</option></select></section><section class="panel wide"><div id="board" class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr))"></div></section>''','''let tasks;try{tasks=JSON.parse(localStorage.getItem('taskflow.tasks')||'[]');if(!Array.isArray(tasks))tasks=[]}catch{tasks=[]}const save=()=>localStorage.setItem('taskflow.tasks',JSON.stringify(tasks));function render(){show('#summary',tasks.length+' tasks · '+tasks.filter(t=>t.status==='Done').length+' completed');const statuses=$('#filter').value==='all'?['Todo','Doing','Done']:[$('#filter').value];$('#board').replaceChildren();for(const status of statuses){const col=document.createElement('section');col.style.cssText='min-width:0;border:1px solid #2a3e4e;border-radius:12px;padding:15px;background:#0b121d';const title=document.createElement('h2');title.textContent=status;col.append(title);for(const t of tasks.filter(t=>t.status===status)){const item=document.createElement('article');item.style.cssText='background:#14202c;padding:12px;border-radius:8px;border:1px solid #2c3f51;margin:9px 0';const p=document.createElement('div');p.textContent=t.title;const small=document.createElement('small');small.textContent=t.priority+' priority';small.style.color='#aebec5';const actions=document.createElement('div');actions.className='actions';for(const [label,delta]of [['←',-1],['→',1]]){const index=['Todo','Doing','Done'].indexOf(status),next=index+delta;if(next<0||next>2)continue;const b=document.createElement('button');b.textContent=label;b.className='secondary';b.setAttribute('aria-label','Move task '+label);b.onclick=()=>{t.status=['Todo','Doing','Done'][next];save();render()};actions.append(b)}const del=document.createElement('button');del.textContent='×';del.className='danger';del.setAttribute('aria-label','Delete task');del.onclick=()=>{tasks=tasks.filter(x=>x.id!==t.id);save();render()};actions.append(del);item.append(p,small,actions);col.append(item)}$('#board').append(col)}}$('#add').onclick=()=>{const title=$('#task').value.trim();if(!title)return;tasks.push({id:Date.now()+Math.random(),title,priority:$('#priority').value,status:'Todo'});$('#task').value='';save();render()};$('#task').addEventListener('keydown',e=>{if(e.key==='Enter')$('#add').click()});$('#clear').onclick=()=>{tasks=tasks.filter(t=>t.status!=='Done');save();render()};$('#filter').onchange=render;render();''')

add('prompt-lab','Prompt Lab','AI / LLM','🤖','Compose structured LLM instructions and estimate context size—no API key or hidden model calls.', '''<section class="panel"><h2>Prompt design controls</h2><label for="persona">System persona</label><select id="persona"><option>Cybersecurity analyst</option><option>Python code reviewer</option><option>Data scientist</option><option>Career coach</option></select><label for="task">User task</label><textarea id="task">Explain the principle of least privilege to a junior IAM analyst.</textarea><label for="context">Supporting context</label><textarea id="context">Audience: new hires. Prefer practical examples. Avoid unsupported claims.</textarea><label for="format">Output style</label><select id="format"><option>Concise explanation with examples</option><option>JSON object with answer and sources</option><option>Numbered implementation checklist</option></select><div class="actions"><button id="build">Compose prompt</button><button class="secondary" id="copy">Copy prompt</button></div></section><section class="panel"><h2>Generated prompt</h2><div id="output" class="output"></div><div class="pill" id="tokens"></div><p class="tiny">Token count is a rough characters ÷ 4 estimate. This is a prompt-construction tool, not a live LLM chat.</p></section>''','''let prompt='';function build(){prompt=['SYSTEM: You are a '+$('#persona').value+'. Be accurate, explain limitations, and do not invent evidence.','TASK: '+$('#task').value.trim(),'CONTEXT: '+$('#context').value.trim(),'RESPONSE FORMAT: '+$('#format').value,'If information is missing, clearly say what is unknown.'].join('\\n\\n');show('#output',prompt);show('#tokens','~'+Math.ceil(prompt.length/4)+' estimated tokens')}$('#build').onclick=build;$('#copy').onclick=()=>prompt&&navigator.clipboard.writeText(prompt);for(const id of ['persona','task','context','format'])$('#'+id).addEventListener('input',build);build();''')

(ROOT/'apps.json').write_text(json.dumps(apps,ensure_ascii=False,indent=2),encoding='utf8')
